        state: [E(.document, 3, "Pawn Ticket", "{D}'s ID."), E(.document, 3, "Serial", "Matches {V}'s receipt.")],
        defense: [E(.statement, 1, "Gift", "{DL} says it was a gift.")],
        role: "Roommate",
        exam: [.direct("How do you know {DL}?", "\"{DL} moved in as a roommate a few weeks before my amplifier went missing from the living room.\""), .direct("What was missing?", "\"A guitar amplifier I bought for nine hundred dollars, which I use for gigs and lessons.\""), .direct("How did you find out where it went?", "\"A pawn shop called about a serial number that matched my receipt, and {DL}'s ID was on the pawn ticket.\""), .direct("What does the ticket show?", "\"It shows {DL} pawned my amplifier for a loan, signed the ticket, and used {D.his} own driver's license.\""), .direct("Did you give {DL} the amplifier?", "\"No. I never said {D.he} could take it, sell it, or pawn it.\""), .direct("What did {DL} say?", "\"{D.He} said it was a gift from me for helping with the rent, which isn't true.\""), .cross("You and {DL} are friends?", "\"We got along as roommates, but I never gave {D.him} anything of that value.\""), .cross("You'd lent {DL} things before?", "\"Small things, like a charger or a pan, but never my amplifier.\""), .cross("{DL} used {D.his} real ID at the pawn shop?", "\"Yes, and that's how the shop and the deputy identified {D.him}.\""), .cross("You didn't have it locked up?", "\"No. It was in the living room where {DL} could see it every day.\""), .cross("You've since recovered it?", "\"Yes, the pawn shop returned it after the deputy confirmed the serial number.\"")],
        theory: ("{D} pawned an amp.", "A gift."),
        allocution: "\"{V} gave me that amplifier, or so I believed, and I pawned it. I've been in this courtroom before, and I know I should have gotten it in writing. I'll get it back out of the pawn shop and return it, and I'll apologize.\"",
        truths: ("No text of a gift exists.", "A text from {V} said 'sell the amp if you need rent'."),
        defendant: [.direct("How did you get the amplifier?", "\"I thought {V} had given it to me. We'd talked about my helping with the rent, and I took it as a gift.\""), .direct("Why did you pawn it?", "\"I was short on money and thought I could redeem it before {V.he} noticed. I should have asked.\""), .direct("Did {V} tell you it was a gift?", "\"I believed it was. We'd joked about it, and I took that as permission. I was wrong.\""), .direct("What happened at the pawn shop?", "\"I showed my ID and signed the ticket. I didn't hide who I was. I meant to get it back.\""), .direct("What did you do when {V} found out?", "\"I told {V.him} the truth and offered to pay the ticket and get the amplifier back.\""), .direct("What would you tell {V}?", "\"I'm sorry for taking it without asking. I'll cover the loan and any damage.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I should have known better than to take something that wasn't mine.\""), .cross("You pawned a roommate's amplifier?", "\"I did, and I know that's wrong. I should have asked or found other money.\""), .cross("You told the deputy it was a gift?", "\"I did, and I wasn't honest enough. I'm sorry.\""), .cross("You used your own ID?", "\"Yes. I thought I'd get it back right away and no one would be hurt.\""), .cross("You'll pay {V} back?", "\"Yes, the full cost of getting it back and an apology.\"")],
        openings: ("A few weeks after {D} moved in as a roommate, {V}'s $900 amplifier disappeared from the living room, and {D} pawned an amplifier whose serial number matches {V}'s receipt, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say the amplifier was a gift from {V} and that {D} believed it was {D.his} to sell. {D} pawned it openly with {D.his} own ID."),
        closings: ("The pawn ticket carries {D}'s ID, the serial number matches {V}'s receipt, and after {PRIOR} {DL} knew whose amplifier it was and that a roommate cannot simply sell a roommate's property.", "A gift between roommates is a gift, and {D} pawned it under {D.his} own name. The State must prove {V} did not give it."),
        timeline: [(-3, "{V} is away."), (0, "{DL} pawns the amp.")],
        identified: "A pawn ticket.",
        mood: .wantsConviction)

    static let placardAgain = SmallCases.make(
