        defense: [E(.statement, 1, "Borrowed", "{DL} says it was borrowed.")],
        role: "Parking officer",
        exam: [.direct("What is your job?", "\"I'm a parking officer. I check permits, placards, and plates in lots and on streets, including accessible spaces.\""), .direct("What did you find on {DL}'s car?", "\"A parking placard hanging from the mirror in an accessible space, which looked copied and not a real issued placard.\""), .direct("How could you tell it was copied?", "\"The colors were faded, the number was blurry, and the card was laminated in a way the state doesn't do.\""), .direct("What did the registry show?", "\"The registry showed no permit issued under that number or to {DL}, so the placard was not valid.\""), .direct("Where did you find it?", "\"In a space designated for accessible parking, where only valid permit holders may park.\""), .direct("What did {DL} say?", "\"{D.He} said it was borrowed from a relative who is disabled and didn't know it was a copy.\""), .cross("Many people borrow placards from relatives?", "\"Some do, which is why I checked the number and the registry.\""), .cross("{DL} wasn't hiding the placard?", "\"No. It was hanging in plain view on the mirror.\""), .cross("You didn't see {DL} make the copy?", "\"No. I only know it wasn't an original and wasn't registered.\""), .cross("{DL} gave you the relative's name?", "\"Yes, {D.he} did. We couldn't find a placard issued under that name either.\""), .cross("{DL} was cooperative?", "\"Yes, {D.he} handed it over without argument.\"")],
        theory: ("{D} used a copy.", "Borrowed."),
        allocution: "\"I borrowed that placard from someone, and I put it on my mirror without checking if it was valid. I've been in this courtroom before, and I know I should have known better. I'll get my own permit or find another place to park.\"",
        truths: ("The scan matched earlier copies.", "The placard was a gift from a disabled relative who asked {DL} to drive."),
        defendant: [.direct("Where did you get the placard?", "\"A relative gave it to me to use when I took {D.him} to appointments, and I left it on the mirror afterward.\""), .direct("Did you know it was copied?", "\"No. It looked like a real card to me. I never examined it closely.\""), .direct("Why were you in the accessible space?", "\"I was dropping off paperwork for my relative and it was the closest space. I thought the placard covered it.\""), .direct("What did you do when the officer came?", "\"I handed over the placard and told the officer exactly where I got it.\""), .direct("Did you make the placard?", "\"No. I wouldn't know how to copy one. I didn't print or laminate anything.\""), .direct("What would you tell the court?", "\"I'm sorry for using a placard I didn't check. I'll never use another one unless it's issued in my name.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I should have known to be careful with permits.\""), .cross("You parked in an accessible space with a copied placard?", "\"I did, and I didn't realize it was copied. I should have verified it.\""), .cross("The registry has no record of it?", "\"So the officer says. I trusted my relative and shouldn't have.\""), .cross("You left it on your mirror?", "\"Yes, and I know that looks like I was using it. I'll take it down.\""), .cross("You'll avoid accessible spaces?", "\"Yes. I'll park elsewhere and leave those spaces for people who need them.\"")],
        openings: ("A parking officer found a parking placard hanging from {D}'s mirror in an accessible space, which looked copied, and the registry shows no such permit, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say the placard was borrowed from a relative and {D} did not know it was a copy. {D} did not make it and did not buy it."),
        closings: ("The registry shows no such permit and the placard looked copied, and after {PRIOR} {DL} knew a copied placard is not a real one.", "A borrowed placard that looks real is not proof that {D} knew it was a copy, and {D} neither made nor bought it. The State must prove {D} knew the placard was not a genuine permit."),
        timeline: [(0, "The officer checks the placard.")],
        identified: "Registry.",
        mood: .indifferent,
        genders: ["D": .male])

